        for vip in [True, False]:
            for priority in reversed(self.PRIORITIES):
                if self.queue[(vip, priority)]:
                    ticket_id = self.queue[(vip, priority)].popleft()
                    return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self.tickets:
            raise ValueError("Ticket not found")
        self.tickets[ticket_id] = (*self.tickets[ticket_id][:4], True)
        self.closed_tickets.add(ticket_id)

    def reopen(self, ticket_id: int) -> None:
        if ticket_id in self.closed_tickets:
            raise ValueError("Cannot reopen a closed ticket")
        if ticket_id not in self.tickets:
            raise ValueError("Ticket not found")
        self.tickets[ticket_id] = (*self.tickets[ticket_id][:4], False)
        self._add_to_queue(ticket_id)

    def _add_to_queue(self, ticket_id: int):
        customer, _, priority, _, _ = self.tickets[ticket_id]
        vip = self.customers[customer]
        self.queue[(vip, priority)].append(ticket_id)

    def queue_length(self) -> int:
        return sum(len(queue) for queue in self.queue.values())

    def ticket(self, ticket_id: int) -> dict:
        if ticket_id not in self.tickets:
            raise ValueError("Ticket not found")
        customer, title, priority, description, closed = self.tickets[ticket_id]
        return {
            "id": ticket_id,
            "customer": customer,
            "title": title,
            "priority": priority,
            "description": description,
            "closed": closed
        }

    def tickets_of(self, customer: str) -> list[int]:
        if customer not in self.customers:
            raise ValueError("Customer not found")
        return [ticket_id for ticket_id, ticket in self.tickets.items() if ticket[0] == customer]

# Example usage:
